from g import *
S = SETUP_STD
AIH = lambda name, sysmsg, user_js: N(name, 'n8n-nodes-base.httpRequest', 4.2, {'method': 'POST', 'url': "={{ $('Config').first().json.aiBaseUrl }}", 'authentication': 'genericCredentialType', 'genericAuthType': 'httpHeaderAuth', 'sendBody': True, 'specifyBody': 'json', 'jsonBody': "={{ JSON.stringify({model:$('Config').first().json.aiModel,response_format:{type:'json_object'},messages:[{role:'system',content:" + __import__('json').dumps(sysmsg) + "},{role:'user',content:" + user_js + "}]}) }}", 'options': {}}, {'httpHeaderAuth': {'id': '', 'name': 'AI API key (Header Auth)'}})
