A('35', 'resume-screener', 'AI resume screener', 'HR', 'Scores each applicant against your job description, shortlists the top candidates to Slack with reasons and sends a polite decline to the rest.',
 ('webhook', 'applicant'), [cfg(jobTitle='Customer Success Manager', jobRequirements='3+ years SaaS support, strong writing, Zendesk, comfortable with refunds and escalations', shortlistScore='75'), norm("return [{json:{name:b.name,email:b.email,resume:String(b.resume_text||'').slice(0,8000)}}];"),
  ai('Screen', 'Screen a resume fairly against the requirements. Judge only job-relevant evidence; ignore name, age, gender, photo, address. JSON: {"score":0-100,"strengths":[""],"gaps":[""],"recommend":"interview|decline"}', "JSON.stringify({job:$('Config').first().json.jobTitle,requirements:$('Config').first().json.jobRequirements,resume:$json.resume})"),
  iff("$json.ai.score >= Number($('Config').first().json.shortlistScore)", [slack('Shortlist', "'SHORTLIST ' + $json.name + ' (' + $json.email + ') score ' + $json.ai.score + '. Strengths: ' + $json.ai.strengths.join('; ') + '. Gaps: ' + $json.ai.gaps.join('; ')")], [mail('Polite decline', '$json.email', "'Your application to ' + $('Config').first().json.businessName", "'Hi ' + $json.name + ', thank you for applying for ' + $('Config').first().json.jobTitle + '. We have decided to move forward with other candidates. We will keep your details on file.'")])],
 {'name': 'Ian Ross', 'email': 'ian@x.com', 'resume_text': '5 years Zendesk support lead at SaaS company...'}, ['Keep a human in the loop: this tool shortlists, it does not decide. Review local hiring-law guidance on automated screening.'] + S, {'AI: Screen': {'score': 82, 'strengths': ['Zendesk', 'SaaS'], 'gaps': ['No refunds experience'], 'recommend': 'interview'}}, ['Shortlist'], ['Polite decline'])
