A('36', 'new-hire-onboarding', 'New hire onboarding checklist', 'HR', 'When a hire is marked accepted it emails the new employee their first-week plan, creates a manager checklist and alerts IT and finance.',
 ('webhook', 'new-hire'), [cfg(itEmail='it@yourdomain.com', hrEmail='hr@yourdomain.com'), norm("return [{json:{name:b.name,email:b.email,role:b.role||'Team member',start:b.start_date,manager:b.manager||'your manager'}}];"),
  mail('Welcome new hire', '$json.email', "'Welcome to ' + $('Config').first().json.businessName + ', ' + $json.name", "'Hi ' + $json.name + ',\\n\\nWe are excited for you to start as ' + $json.role + ' on ' + $json.start + '. Your first week: Day 1 meet ' + $json.manager + ' and set up accounts; Day 2 tools and training; Day 3 shadow the team; Day 5 first goals.\\n\\nSee you soon!'"),
  mail('Notify IT', "$('Config').first().json.itEmail", "'Equipment and accounts for ' + $('Normalize').first().json.name", "'Please prepare a laptop and accounts for ' + $('Normalize').first().json.name + ' (' + $('Normalize').first().json.role + ') starting ' + $('Normalize').first().json.start + '.'"),
  row('Row: checklist', "return [{json:{name:j.name,start:j.start,manager:j.manager,laptop:'TODO',accounts:'TODO',payroll:'TODO',day1_meeting:'TODO'}}];"), sheet_append('Create checklist')],
 {'name': 'Nia Cole', 'email': 'nia@x.com', 'role': 'Designer', 'start_date': '2026-12-07', 'manager': 'Sam'}, S, {}, ['Welcome new hire', 'Notify IT', 'Create checklist'])
