A('37', 'meeting-actions-to-tasks', 'Meeting notes to action items and tasks', 'Ops', 'Send a meeting transcript (Zoom, Fathom, Otter webhook) and AI extracts decisions and action items with owners, creates tasks in Linear or any tracker API and posts the summary to Slack.',
 ('webhook', 'meeting-notes'), [cfg(trackerUrl='https://api.linear.app/graphql'), norm("return [{json:{title:b.title||'Meeting',transcript:String(b.transcript||'').slice(0,15000),attendees:b.attendees||[]}}];"),
  ai('Extract actions', 'Extract from the meeting. JSON: {"summary":"3 sentences","decisions":[""],"actions":[{"task":"","owner":"","due":"YYYY-MM-DD or empty"}]}', "JSON.stringify($json)"),
  code('Split tasks', "const j=$input.first().json;const acts=(j.ai.actions||[]);if(!acts.length)return [{json:{...j,none:true}}];return acts.map(a=>({json:{title:j.title,task:a.task,owner:a.owner||'unassigned',due:a.due||'',summary:j.ai.summary}}));"),
  iff('!$json.none', [http('Create task', 'POST', "={{ $('Config').first().json.trackerUrl }}", "{title:$json.task,description:'From meeting: ' + $json.title + ' (owner ' + $json.owner + ', due ' + ($json.due || 'n/a') + ')'}", 'Tracker API (Header Auth)')]),
  ],
 {'title': 'Weekly sync', 'transcript': 'Sam will send the proposal by Friday. Lee to fix the login bug.', 'attendees': ['Sam', 'Lee']}, ['Replace the Create task body with your tracker format (Linear, Asana, ClickUp, Trello all accept JSON).'] + S, {'AI: Extract actions': {'summary': 'Sync.', 'decisions': ['Ship Friday'], 'actions': [{'task': 'Send proposal', 'owner': 'Sam', 'due': '2026-12-04'}, {'task': 'Fix login bug', 'owner': 'Lee', 'due': ''}]}}, ['Create task'])
