A('38', 'github-daily-digest', 'Engineering daily standup digest from GitHub', 'Ops', 'Pulls yesterday\'s commits and merged pull requests from GitHub and has AI write a standup summary for Slack.',
 cron(9, 5), [cfg(repo='your-org/your-repo'), code('Since', "const s=new Date(Date.now()-864e5).toISOString();return [{json:{since:s}}];"),
  http('GitHub commits', 'GET', "={{ 'https://api.github.com/repos/' + $('Config').first().json.repo + '/commits' }}", None, 'GitHub (Header Auth: Authorization = Bearer ghp_...)', query="{since:$json.since,per_page:50}"),
  N('Normalize', 'n8n-nodes-base.code', 2, {'jsCode': "const c=$input.all().map(i=>i.json).filter(x=>x&&x.commit);return [{json:{count:c.length,commits:c.map(x=>(x.commit.author&&x.commit.author.name)+': '+String(x.commit.message).split('\\n')[0])}}];"}),
  iff('$json.count > 0', [ai('Standup', 'Write a crisp standup summary grouped by theme. JSON: {"summary":"","risks":[""]}', "JSON.stringify($json.commits)"), slack('Post standup', "'Yesterday (' + $json.count + ' commits)\\n' + $json.ai.summary + ($json.ai.risks && $json.ai.risks.length ? '\\nWatch: ' + $json.ai.risks.join('; ') : '')")])],
 {}, S[1:], {'GitHub commits': [{'commit': {'author': {'name': 'Ana'}, 'message': 'Fix login redirect\n\nbody'}}, {'commit': {'author': {'name': 'Lee'}, 'message': 'Add CSV export'}}], 'AI: Standup': {'summary': 'Login fixed, CSV export added.', 'risks': []}}, ['Post standup'])
