A('39', 'issue-triage', 'GitHub or support issue labeller', 'Ops', 'New GitHub issue webhook gets labelled (bug, feature, question), priority and a suggested first reply via the GitHub API.',
 ('webhook', 'gh-issue'), [cfg(repo='your-org/your-repo'), norm("const i=b.issue||{};return [{json:{number:i.number,title:i.title||'',body:String(i.body||'').slice(0,3000),action:b.action||'opened'}}];"),
  iff("$json.action === 'opened'", [ai('Label', 'Triage a software issue. JSON: {"labels":["bug|feature|question|docs"],"priority":"p0|p1|p2","reply":"a helpful first reply asking for missing details"}', "JSON.stringify($json)"),
   http('Add labels', 'POST', "={{ 'https://api.github.com/repos/' + $('Config').first().json.repo + '/issues/' + $json.number + '/labels' }}", "{labels:$json.ai.labels.concat([$json.ai.priority])}", 'GitHub (Header Auth: Authorization = Bearer ghp_...)'),
   http('Post first reply', 'POST', "={{ 'https://api.github.com/repos/' + $('Config').first().json.repo + '/issues/' + $('Normalize').first().json.number + '/comments' }}", "{body:$('Parse: Label').first().json.ai.reply}", 'GitHub (Header Auth: Authorization = Bearer ghp_...)')])],
 {'action': 'opened', 'issue': {'number': 77, 'title': 'App crashes on export', 'body': 'Click export and it crashes.'}}, S, {'AI: Label': {'labels': ['bug'], 'priority': 'p1', 'reply': 'Thanks! Which browser?'}}, ['Add labels', 'Post first reply'])
