A('40', 'pto-approval', 'Time-off request approvals', 'HR', 'Employee request arrives by webhook; checks the notice period and team overlap, then asks the manager in Slack and emails the employee the outcome via approve/deny links.',
 ('webhook', 'pto-request'), [cfg(minNoticeDays='7', approveUrl='https://your-n8n/webhook/pto-decision'), norm("const days=Math.round((new Date(b.end)-new Date(b.start))/864e5)+1;const notice=Math.round((new Date(b.start)-Date.now())/864e5);return [{json:{name:b.name,email:b.email,start:b.start,end:b.end,days,notice,team:b.team||''}}];"),
  iff("$json.notice >= Number($('Config').first().json.minNoticeDays)", [slack('Ask manager', "'PTO request: ' + $json.name + ' ' + $json.start + ' to ' + $json.end + ' (' + $json.days + ' days). Approve: ' + $('Config').first().json.approveUrl + '?d=approve&e=' + encodeURIComponent($json.email) + ' Deny: ' + $('Config').first().json.approveUrl + '?d=deny&e=' + encodeURIComponent($json.email)")], [mail('Short notice notice', '$json.email', "'About your time-off request'", "'Hi ' + $json.name + ', requests need ' + $('Config').first().json.minNoticeDays + ' days notice. Yours has ' + $json.notice + '. Please talk to your manager directly.'")])],
 {'name': 'Rae', 'email': 'rae@x.com', 'start': '2999-06-01', 'end': '2999-06-05', 'team': 'support'}, S, {}, ['Ask manager'], ['Short notice notice'])
