A('41', 'low-stock-po', 'Low-stock alert and purchase-order draft', 'Ecommerce', 'Daily inventory sheet check. Items at or below reorder point get grouped by supplier into a ready-to-send purchase-order email.',
 cron(7), [cfg(), sheet_read('Read inventory'),
  code('Group by supplier', "const by={};for(const it of $input.all()){const r=it.json;const stock=Number(r.stock),rp=Number(r.reorder_point);if(isNaN(stock)||isNaN(rp)||stock>rp)continue;const qty=Math.max(Number(r.reorder_qty||0),rp*2-stock);(by[r.supplier_email]=by[r.supplier_email]||[]).push(r.sku+' - '+r.name+': order '+qty+' (stock '+stock+')');}const out=Object.entries(by).map(([email,lines])=>({json:{email,lines:lines.join('\\n'),n:lines.length}}));return out.length?out:[{json:{none:true}}];"),
  iff('!$json.none', [mail('Email PO draft', "$('Config').first().json.emailTo", "'PO draft for ' + $json.email + ' (' + $json.n + ' items)'", "'Forward to ' + $json.email + ':\\n\\nHello, please quote and ship:\\n' + $json.lines + '\\n\\nThank you,\\n' + $('Config').first().json.businessName"), slack('Alert: low stock', "$json.n + ' item(s) low for supplier ' + $json.email")])],
 {}, ['Sheet columns: sku, name, stock, reorder_point, reorder_qty, supplier_email.'] + S[1:], {'Read inventory': [{'sku': 'A1', 'name': 'Mug', 'stock': '4', 'reorder_point': '10', 'reorder_qty': '40', 'supplier_email': 'sup@x.com'}, {'sku': 'B2', 'name': 'Tote', 'stock': '50', 'reorder_point': '10', 'reorder_qty': '40', 'supplier_email': 'sup@x.com'}]}, ['Email PO draft', 'Alert: low stock'])
