A('42', 'shipping-delay-notifier', 'Proactive shipping delay notifier', 'Ecommerce', 'Daily check of open orders; emails customers whose order is late or stuck with a sincere update and a small goodwill code, and tells you the list.',
 cron(10), [cfg(goodwillCode='SORRY10'), sheet_read('Read orders'),
  code('Find delayed', "const out=[];for(const it of $input.all()){const r=it.json;if(String(r.status).toLowerCase()==='delivered')continue;const age=Math.floor((Date.now()-new Date(r.shipped_on).getTime())/864e5);if(age>Number(r.promised_days||7))out.push({json:{order:r.order,name:r.name,email:r.email,age,promised:Number(r.promised_days||7)}});}return out.length?out:[{json:{none:true}}];"),
  iff('!$json.none', [mail('Delay email', '$json.email', "'An update on order ' + $json.order", "'Hi ' + $json.name + ', your order ' + $json.order + ' is taking longer than the ' + $json.promised + ' days we promised. We are chasing the carrier and are sorry. Use ' + $('Config').first().json.goodwillCode + ' for 10% off your next order.'"), slack('Log: delayed order', "'Delay notice sent for order ' + $json.order + ' (' + $json.age + ' days)'")])],
 {}, ['Sheet columns: order, name, email, status, shipped_on, promised_days.'] + S[1:], {'Read orders': [{'order': '#1001', 'name': 'Al', 'email': 'a@x.com', 'status': 'In transit', 'shipped_on': '2020-01-01', 'promised_days': '7'}, {'order': '#1002', 'name': 'Bo', 'email': 'b@x.com', 'status': 'Delivered', 'shipped_on': '2020-01-01'}]}, ['Delay email', 'Log: delayed order'])
