A('44', 'rfm-winback', 'Customer win-back by RFM segment', 'Ecommerce', 'Weekly segments customers by recency and spend, sends a personalised win-back to lapsed high-value customers and a gentle nudge to others.',
 weekly(2, 10), [cfg(winbackCode='MISSYOU15'), sheet_read('Read customers'),
  code('Segment', "const out=[];for(const it of $input.all()){const r=it.json;const rec=Math.floor((Date.now()-new Date(r.last_order).getTime())/864e5);const spend=Number(r.total_spent||0);if(isNaN(rec)||!r.email)continue;if(rec>=90&&rec<=365){out.push({json:{name:r.name,email:r.email,rec,spend,tier:spend>=300?'vip':'standard'}});}}return out.length?out:[{json:{none:true}}];"),
  iff('!$json.none', [iff("$json.tier === 'vip'", [mail('VIP win-back', '$json.email', "$json.name + ', we saved you something'", "'Hi ' + $json.name + ', it has been ' + $json.rec + ' days and we miss you. As one of our best customers here is 20% off: VIP20.'")], [mail('Standard win-back', '$json.email', "'We miss you, ' + $json.name", "'Hi ' + $json.name + ', here is ' + $('Config').first().json.winbackCode + ' for 15% off your next order.'")])])],
 {}, ['Sheet columns: name, email, last_order (YYYY-MM-DD), total_spent.'] + S[1:], {'Read customers': [{'name': 'Vi', 'email': 'v@x.com', 'last_order': '__AGO100__', 'total_spent': '520'}, {'name': 'Sy', 'email': 's@x.com', 'last_order': '__AGO100__', 'total_spent': '60'}, {'name': 'New', 'email': 'n@x.com', 'last_order': '__AGO3__', 'total_spent': '99'}]}, ['VIP win-back', 'Standard win-back'])
