A('45', 'appointment-reminders', 'Appointment reminders (24h and 2h)', 'Local business', 'Every 15 minutes checks the booking sheet and sends SMS or email reminders 24 hours and 2 hours before an appointment, with a reply-to-confirm prompt, cutting no-shows.',
 mins(15), [cfg(twilioSid='ACXXXXXXXX'), sheet_read('Read bookings'),
  code('Find reminders', "const now=Date.now();const out=[];for(const it of $input.all()){const r=it.json;if(String(r.status).toLowerCase()==='cancelled')continue;const mins=Math.round((new Date(r.start).getTime()-now)/6e4);if(mins>=1425&&mins<1440&&!r.sent24)out.push({json:{name:r.name,phone:r.phone,start:r.start,kind:'24h'}});if(mins>=105&&mins<120&&!r.sent2)out.push({json:{name:r.name,phone:r.phone,start:r.start,kind:'2h'}});}return out.length?out:[{json:{none:true}}];"),
  iff('!$json.none', [http('Send reminder SMS', 'POST', "={{ 'https://api.twilio.com/2010-04-01/Accounts/' + $('Config').first().json.twilioSid + '/Messages.json' }}", None, 'Twilio (Basic Auth)', form={'To': '$json.phone', 'From': "$('Config').first().json.twilioFrom", 'Body': "'Hi ' + $json.name + ', reminder of your appointment with ' + $('Config').first().json.businessName + ' ' + ($json.kind === '24h' ? 'tomorrow' : 'in 2 hours') + ' at ' + $json.start + '. Reply C to confirm or R to reschedule.'"})])],
 {}, ['Sheet columns: name, phone, start (ISO datetime), status, sent24, sent2. Add Sheet update nodes to set sent24/sent2 (see sticky).'] + S[1:], {'Read bookings': [{'name': 'Cy', 'phone': '+15550002222', 'start': '__IN24H__', 'status': 'Booked'}]}, ['Send reminder SMS'])
